// @matrix 64x128
// @knobs Agents=100..400, Turbo=1..20, Void_Size=5..30, Wiggle=0..1
// Patternflow layer-stack composition — flattened by Pattern Lab.
// Layers (bottom → top):
//   1. Neural Serotonin (code, normal, 100%)
//   2. happy (pixel, normal, 100%)
const __W = 64, __H = 128;
const __stack = [];

function __b64(s, n) {
  const A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out = new Uint8ClampedArray(n);
  let o = 0, buf = 0, bits = 0;
  for (let i = 0; i < s.length && o < n; i++) {
    const v = A.indexOf(s[i]);
    if (v < 0) continue;
    buf = (buf << 6) | v; bits += 6;
    if (bits >= 8) { bits -= 8; out[o++] = (buf >> bits) & 255; }
  }
  return out;
}

function __mkDisplay(L) {
  return {
    width: __W, height: __H,
    setPixel(x, y, r, g, b) {
      const xi = x | 0, yi = y | 0;
      if (xi < 0 || xi >= __W || yi < 0 || yi >= __H) return;
      const i = (yi * __W + xi) * 4, B = L.buf;
      if (Array.isArray(r)) { B[i] = r[0] || 0; B[i + 1] = r[1] || 0; B[i + 2] = r[2] || 0; }
      else { B[i] = r; B[i + 1] = g || 0; B[i + 2] = b || 0; }
      B[i + 3] = 255;
    },
    setValue(x, y, v) {
      const xi = x | 0, yi = y | 0;
      if (xi < 0 || xi >= __W || yi < 0 || yi >= __H) return;
      v = Number.isFinite(v) ? (v < 0 ? 0 : v > 1 ? 1 : v) : 0;
      const i = (yi * __W + xi) * 4, B = L.buf, T = L.lut;
      if (T) {
        const li = Math.round(v * 255) * 4;
        B[i] = T[li]; B[i + 1] = T[li + 1]; B[i + 2] = T[li + 2]; B[i + 3] = T[li + 3];
      } else {
        const byte = Math.round(v * 255);
        B[i] = byte; B[i + 1] = byte; B[i + 2] = byte; B[i + 3] = 255;
      }
    },
  };
}

// ── code layer: Neural Serotonin ──
(function () {
  // Shadow the wrapper's own exports: a layer that defines no setup/update
  // must yield undefined here, not capture the OUTER setup (infinite loop).
  var setup, update, draw;

function setup(params) {
  params.w = 120;
  params.h = 120;
  const size = params.w * params.h;
  
  params.trailMap = new Float32Array(size).fill(0);
  params.agents = [];

  for (let i = 0; i < 800; i++) {
    params.agents.push({
      x: params.w / 2,
      y: params.h / 2
    });
  }
}

function update(dt, input, params) {
  params.k = input.knobValues;
  const [numAgents, turbo, voidSize, wiggle] = params.k;
  const w = params.w, h = params.h;
  const midX = w / 2, midY = h / 2;

  // 1. MOVEMENT LOGIC
  for (let g = 0; g < Math.floor(turbo); g++) {
    for (let i = 0; i < Math.floor(numAgents); i++) {
      let a = params.agents[i];

      // Wiggle influence: Higher wiggle adds random jitter to the direction
      const isWiggling = Math.random() < wiggle;
      
      if (isWiggling) {
        // Jagged, unpredictable motion
        a.x += (Math.random() - 0.5) * 3;
        a.y += (Math.random() - 0.5) * 3;
      } else {
        // Strict, Biased Circuit Logic
        if (Math.random() < 0.5) {
          if (a.x < midX - voidSize) a.x += (Math.random() < 0.9 ? -1 : 1);
          else if (a.x > midX + voidSize) a.x += (Math.random() < 0.9 ? 1 : -1);
          else a.x += (Math.random() - 0.5) * 2; 
        } else {
          if (a.y < midY - voidSize) a.y += (Math.random() < 0.9 ? -1 : 1);
          else if (a.y > midY + voidSize) a.y += (Math.random() < 0.9 ? 1 : -1);
          else a.y += (Math.random() - 0.5) * 2;
        }
      }

      // Auto-Respawn to keep activity high
      if (a.x < 0 || a.x >= w || a.y < 0 || a.y >= h || Math.random() < 0.015) {
        a.x = midX + (Math.random() - 0.5) * (voidSize * 1.2);
        a.y = midY + (Math.random() - 0.5) * (voidSize * 1.2);
      }

      let idx = Math.floor(a.x) + Math.floor(a.y) * w;
      if (idx >= 0 && idx < params.trailMap.length) {
        params.trailMap[idx] = 1.0; 
      }
    }
  }

  // 2. DECAY
  for (let i = 0; i < params.trailMap.length; i++) {
    params.trailMap[i] *= 0.96; 
  }
}

function draw(display, params, time) {
  const w = display.width, h = display.height;
  const simW = params.w, simH = params.h;

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const sx = Math.floor((x / w) * simW);
      const sy = Math.floor((y / h) * simH);
      const val = params.trailMap[sx + sy * simW];

      if (val > 0.01) {
        // Quadrant Color Mapping (Original Reference Logic)
        const r = (80 + Math.sin(time) * 20) * val;
        const g = (50 + (sx / simW) * 205) * val;
        const b = (50 + (sy / simH) * 205) * val;

        display.setPixel(x, y, r, g, b);
      } else {
        display.setPixel(x, y, 0, 0, 0);
      }
    }
  }
}
  __stack.push({
    kind: "code", opacity: 1, blend: "normal", recolor: true, role: "paint", maskInvert: false,
    lut: [0,0,0,92,0,0,0,94,0,0,0,98,1,0,0,103,2,0,0,107,3,1,0,111,5,2,0,116,7,4,0,120,9,7,0,124,10,11,0,129,11,16,0,133,8,22,0,137,1,28,0,142,0,32,10,146,0,36,21,151,0,40,29,155,0,44,38,159,0,49,46,164,0,53,55,168,0,57,64,172,0,61,74,177,0,65,86,181,0,68,100,185,0,70,118,190,0,68,145,194,36,65,163,198,61,63,171,203,82,60,176,207,102,57,179,211,121,54,178,216,139,51,175,220,157,46,168,225,175,42,159,229,192,36,146,233,207,29,131,238,222,23,113,242,235,21,91,246,246,26,63,251,255,38,0,255,255,43,45,255,255,47,66,255,255,50,83,255,255,53,97,255,255,56,111,255,255,58,123,255,255,60,136,255,255,61,148,255,255,62,160,255,254,64,172,255,252,69,184,255,249,74,195,255,246,79,206,255,243,83,217,255,239,88,228,255,235,93,238,255,230,98,248,255,224,105,255,255,214,118,255,255,205,128,255,255,198,136,255,255,191,142,255,255,185,148,255,255,180,154,255,255,175,158,255,255,170,163,255,255,166,167,255,255,162,171,255,255,158,175,255,255,154,178,255,255,151,182,255,255,147,185,255,255,144,188,255,255,140,191,255,255,136,194,255,255,132,198,255,255,128,201,255,255,124,204,255,255,119,207,255,255,113,210,255,255,106,213,255,255,96,217,255,255,84,220,255,255,66,224,255,255,29,228,255,255,0,232,252,255,0,234,247,255,0,237,243,255,0,239,238,255,0,242,233,255,0,245,227,255,0,247,222,255,0,250,215,255,0,253,208,255,14,255,200,255,70,255,194,255,96,255,187,255,115,255,181,255,131,255,175,255,145,255,169,255,157,255,163,255,168,255,157,255,179,255,150,255,189,255,142,255,199,255,133,255,208,255,120,255,218,255,101,255,229,255,59,255,241,253,32,255,253,251,4,255,221,255,92,255,190,255,141,255,156,255,164,255,110,255,183,255,0,254,204,255,0,245,226,255,0,237,242,255,34,228,255,255,99,216,255,255,121,205,255,255,135,195,255,255,147,185,255,255,158,174,255,255,171,162,255,255,188,146,255,255,211,121,255,255,234,94,239,255,246,78,206,255,255,63,169,255,255,59,130,255,255,52,88,255,255,39,13,255,255,44,71,255,255,48,106,255,255,49,136,255,255,47,166,255,248,59,196,255,239,70,224,255,228,82,250,255,204,111,255,255,185,131,255,255,169,145,255,255,155,155,255,255,142,164,255,255,129,173,255,255,114,180,255,255,95,188,255,255,64,196,255,255,0,204,251,255,0,209,239,255,0,215,228,255,0,220,216,255,0,225,203,255,0,230,187,255,0,236,166,255,0,242,130,255,0,249,26,255,0,243,123,255,0,238,160,255,0,234,183,255,0,229,200,255,0,225,213,255,0,221,225,255,0,216,236,255,0,212,248,255,51,206,255,255,90,199,255,255,111,192,255,255,126,186,255,255,138,180,255,255,150,173,255,255,161,166,255,255,173,158,255,255,186,148,255,255,201,135,255,255,221,116,255,255,248,78,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255,255,64,255,255],
    buf: new Uint8ClampedArray(__W * __H * 4),
    params: {},
    fSetup: typeof setup === "function" ? setup : null,
    fUpdate: typeof update === "function" ? update : null,
    fDraw: typeof draw === "function" ? draw : null,
  });
})();

// ── pixel layer: happy ──
__stack.push({
  kind: "pixel", opacity: 1, blend: "normal", role: "paint", maskInvert: false,
  buf: __b64("", __W * __H * 4),
});

// Mask grouping: a mask layer paints nothing — it gates the nearest paint
// layer BELOW it (stacked masks intersect). Binary threshold: pixel-art masks
// switch on where alpha >= 0.5, code masks where luminance × alpha >= 0.5.
const __groups = [];
{
  let last = null;
  for (const L of __stack) {
    if (L.role === "mask") { if (last) last.masks.push(L); continue; }
    L.masks = [];
    last = L;
    if (L.opacity > 0) __groups.push(L);
  }
}

function __maskOn(M, j) {
  const B = M.buf;
  let on;
  if (M.kind === "pixel") on = B[j + 3] >= 128;
  else on = (0.2126 * B[j] + 0.7152 * B[j + 1] + 0.0722 * B[j + 2]) * (B[j + 3] / 255) >= 127.5;
  return M.maskInvert ? !on : on;
}

// One shared knob set: every layer receives the same input, exactly like
// patterns running on the device's four physical encoders.
function __mirror(L) {
  const inp = L.lastInput;
  if (!inp) return;
  L.params.knobValues = inp.knobValues;
  L.params.knobNormalized = inp.knobNormalized;
  L.params.knobDeltas = inp.knobDeltas;
  L.params.knobRanges = inp.knobRanges;
  L.params.btnPressed = inp.btnPressed;
  L.params.btnHeld = inp.btnHeld;
}

export function setup(params) {
  for (const L of __stack) {
    if (L.kind !== "code") continue;
    L.display = __mkDisplay(L);
    if (L.fSetup) L.fSetup(L.params);
  }
}

export function update(dt, input, params) {
  for (const L of __stack) {
    if (L.kind !== "code") continue;
    L.lastInput = input;
    __mirror(L);
    if (L.fUpdate) L.fUpdate(dt, input, L.params);
  }
}

export function draw(display, params, time) {
  for (const L of __stack) {
    if (L.kind !== "code" || !L.fDraw) continue;
    L.buf.fill(0);
    __mirror(L);
    L.fDraw(L.display, L.params, time);
    if (L.recolor && L.lut) {
      const B = L.buf, T = L.lut;
      for (let i = 0; i < B.length; i += 4) {
        if (B[i + 3] === 0) continue;
        const lum = Math.round(0.2126 * B[i] + 0.7152 * B[i + 1] + 0.0722 * B[i + 2]) * 4;
        B[i] = T[lum]; B[i + 1] = T[lum + 1]; B[i + 2] = T[lum + 2]; B[i + 3] = T[lum + 3];
      }
    }
  }

  // Composite bottom → top over the panel's opaque black.
  const count = __W * __H;
  for (let i = 0; i < count; i++) {
    const j = i * 4;
    let r = 0, g = 0, b = 0;
    for (const L of __groups) {
      let hidden = false;
      for (let m = 0; m < L.masks.length; m++) {
        if (!__maskOn(L.masks[m], j)) { hidden = true; break; }
      }
      if (hidden) continue;
      const B = L.buf;
      const a = (B[j + 3] / 255) * L.opacity;
      if (a <= 0) continue;
      const sr = B[j], sg = B[j + 1], sb = B[j + 2], inv = 1 - a;
      if (L.blend === "add") { r += sr * a; g += sg * a; b += sb * a; }
      else if (L.blend === "multiply") {
        r = r * inv + ((r * sr) / 255) * a;
        g = g * inv + ((g * sg) / 255) * a;
        b = b * inv + ((b * sb) / 255) * a;
      } else if (L.blend === "screen") {
        r = r * inv + (255 - ((255 - r) * (255 - sr)) / 255) * a;
        g = g * inv + (255 - ((255 - g) * (255 - sg)) / 255) * a;
        b = b * inv + (255 - ((255 - b) * (255 - sb)) / 255) * a;
      } else {
        r = r * inv + sr * a;
        g = g * inv + sg * a;
        b = b * inv + sb * a;
      }
    }
    display.setPixel(i % __W, (i / __W) | 0, r, g, b);
  }
}

